import{_ as e,o as d,c as o,ag as a}from"./chunks/framework.DaCm-iTo.js";const p=JSON.parse('{"title":"事件 API","description":"","frontmatter":{},"headers":[],"relativePath":"modules/item/events.md","filePath":"modules/item/events.md","lastUpdated":null}'),r={name:"modules/item/events.md"};function c(n,t,i,l,s,m){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="事件-api" tabindex="-1">事件 API <a class="header-anchor" href="#事件-api" aria-label="Permalink to &quot;事件 API&quot;">​</a></h1><p>Item 当前只有三个公开事件；源码中不存在 <code>ItemUpdateEvent</code> 或 <code>EquipmentSkillTriggerEvent</code>。事件包为 <code>emaki.jiuwu.craft.item.api.event</code>。</p><table tabindex="0"><thead><tr><th>事件</th><th>触发时机</th><th>线程</th><th>Cancellable</th><th>可修改字段</th><th>取消/结果效果</th><th>runtime 路径</th></tr></thead><tbody><tr><td><code>EmakiItemCreateEvent</code></td><td>factory 已构建 stack、返回调用方前</td><td>global-region owner thread</td><td>是</td><td><code>result</code>，必须非 null</td><td>取消丢弃结果；公开 <code>create</code> 返回 <code>CANCELLED</code></td><td>进入 <code>EmakiItemFactory</code> 且当前拥有 global region 的创建路径</td></tr><tr><td><code>ItemRepairEvent</code></td><td>修复校验后、扣费和恢复耐久前</td><td>玩家 owner thread</td><td>是</td><td><code>restoreAmount</code></td><td>取消不扣费、不修复；<code>&lt;=0</code> 也抑制修复</td><td>材料与经济修复 service，包括公开 <code>repair()</code> 的经济路径</td></tr><tr><td><code>ItemSetBonusChangeEvent</code></td><td>active set count 实际改变后</td><td>玩家 owner thread</td><td>否</td><td>无</td><td>post 通知，不可回滚</td><td>装备套装刷新，每个变化 set id 一次</td></tr></tbody></table><p>当前 factory 创建事件的 player 为 null。若不拥有 global region，runtime 会跳过创建事件并仍返回分离构建结果，因此它不是所有 ItemStack 创建的完整审计流。Migration 和普通 refresh 没有独立公开事件。<code>ItemSetBonusChangeEvent</code> 是 post 事件，不能取消。</p>',4)])])}const u=e(r,[["render",c]]);export{p as __pageData,u as default};
